from format_lecon import Lesson,paras,table,steps
from medicaments import mestinon
l=Lesson('Myasthénie oculaire',7)
l.add('La {myasthénie oculaire altère la transmission neuromusculaire}. Elle provoque ptosis et diplopie fluctuants. Une atteinte initialement oculaire peut se généraliser.',paras('La myasthénie auto-immune touche la jonction entre nerf et muscle, avec des anticorps dirigés notamment contre le récepteur de l’acétylcholine. La fatigabilité augmente à l’effort et s’améliore au repos.', 'On peut décrire une présentation limitée aux muscles oculaires au moment de l’examen. Le CEN réserve la qualification durable de myasthénie oculaire à un recul de deux ans sans généralisation ; cette convention ne justifie pas d’attendre pour diagnostiquer ou traiter.', 'Une paralysie apparente changeant de profil et un ptosis asymétrique orientent. Une pupille anormale n’est pas une manifestation habituelle et demande une autre explication.'),(5,13,21))
l.add('Le {risque de généralisation impose une surveillance clinique}. L’âge de début et le profil immunologique influencent le contexte. Aucun chiffre suisse spécifique au strabisme myasthénique n’est établi ici.',paras('Le CEN décrit des signes oculaires comme présentation initiale fréquente. Les proportions de généralisation rapportées dans des populations différentes ne constituent pas une prédiction individuelle et ne sont pas utilisées pour promettre une évolution bénigne.', 'Une présentation oculaire persistante peut rester limitée, mais une généralisation tardive reste possible. Rechercher maladie thyroïdienne auto-immune et anomalie thymique selon le bilan spécialisé.', 'L’absence de thymome cliniquement apparent ne supprime pas l’indication d’explorer le thymus. Les recommandations allemandes de 2023 intègrent phénotype, anticorps et activité de la maladie aux décisions.'),(13,21))
l.add('Le {défaut postsynaptique réduit la marge de transmission}. Les contractions répétées révèlent une faiblesse variable. La pyridostigmine et les traitements immunologiques agissent à des niveaux différents.',table(['Mécanisme','Conséquence diagnostique','Conséquence thérapeutique'],[['La transmission devient insuffisante à l’effort.','Comparer les signes avant et après sollicitation, puis repos.','Adapter les activités et le traitement symptomatique.'],['Des autoanticorps altèrent la jonction.','Rechercher les anticorps adaptés au contexte.','Discuter un traitement immunologique si le handicap persiste.'],['Les muscles oculaires peuvent être principalement touchés.','Un examen musculaire périphérique négatif ne suffit pas à exclure la forme oculaire.','Orienter l’électrophysiologie dans un centre expérimenté.'],['L’atteinte dépasse les muscles oculaires.','Examiner déglutition, phonation, membres et respiration.','Une atteinte bulbaire ou respiratoire change immédiatement la priorité.']])+paras('Les mécanismes immunologiques ne sont pas identiques dans tous les sous-groupes. La réponse aux anticholinestérasiques peut notamment être différente dans les formes avec anticorps anti-MuSK. Ne pas extrapoler une réponse médicamenteuse isolée à tous les patients.'),(13,21))
l.add('La {priorité est de détecter une atteinte bulbaire ou respiratoire}. Fausses routes, voix qui s’éteint et toux inefficace sont des alarmes. Une dyspnée ou une aggravation rapide impose une prise en charge urgente.',paras('L’orthopnée, l’encombrement et l’essoufflement au moindre effort peuvent précéder une insuffisance respiratoire aiguë. Une présentation jusque-là oculaire n’exclut pas une crise. En Suisse, activer le 144 en cas de détresse ou de dégradation rapide.', 'Une crise cholinergique par excès de pyridostigmine peut également produire faiblesse et atteinte respiratoire. Les signes muscariniques et le contexte de dose orientent, mais la distinction et la décision thérapeutique appartiennent à l’équipe urgente.', 'Un déficit oculomoteur aigu avec mydriase, céphalée importante ou signes centraux doit faire rechercher notamment une paralysie compressive du III ou une cause neurologique. Ne pas attribuer tous les symptômes d’un patient myasthénique à sa maladie connue.'),(5,13,14,16,21))
l.add('L’{anamnèse recherche fluctuation, fatigabilité et signes extraoculaires}. Préciser l’effet du repos et l’évolution dans la journée. Réviser les médicaments et les infections récentes.',paras('Demander si le ptosis change de côté, si la diplopie varie selon l’activité et si les symptômes s’améliorent au repos. Des photographies prises lors des épisodes peuvent aider lorsque l’examen est normal, sans remplacer les tests.', 'Interroger sur mastication fatigable, voix nasonnée, fausses routes, difficulté à tenir la tête, monter les escaliers ou lever les bras. Rechercher une gêne respiratoire, y compris couchée.', 'Identifier introduction ou augmentation d’un médicament, intervention chirurgicale, infection, grossesse ou post-partum. En cas de pyridostigmine, préciser réellement forme, dose, horaires, oublis, effets indésirables et automédication.'),(13,14,21))
l.add('L’{examen observe les variations sans épuiser le patient}. Comparer ptosis, motilité et pupilles. Rechercher une fatigabilité et une faiblesse hors du territoire oculaire.',paras('La fixation prolongée vers le haut peut majorer le ptosis. Le CEN décrit le test au glaçon dans une poche appliquée deux minutes sur la paupière fermée : une amélioration oriente, sans constituer une preuve unique.', 'La motilité peut imiter différentes paralysies et varier pendant l’examen. Mesurer la déviation et l’acuité, examiner les pupilles et rechercher une restriction orbitaire. Une atteinte pupillaire nouvelle relance le diagnostic différentiel.', 'Évaluer voix, déglutition rapportée, force cervicale et des membres, toux et respiration. Ne pas multiplier les épreuves fatigantes en présence de signes de gravité ; l’évaluation urgente prime.'),(5,13,21))
l.add('Les {formes oculaires et généralisées relèvent d’un suivi différent}. Le phénotype clinique se complète par les anticorps et le thymus. La négativité d’un test n’est pas une catégorie de bénignité.',paras('7.1. Une forme limitée aux yeux peut provoquer un handicap majeur par diplopie ou ptosis malgré une force des membres normale. Les objectifs incluent lecture, travail et sécurité des déplacements.', '7.2. Une atteinte bulbaire, axiale, des membres ou respiratoire indique une généralisation et peut nécessiter une intensification du traitement.', '7.3. Les formes associées aux anticorps anti-récepteurs de l’acétylcholine, anti-MuSK, autres anticorps ou sans anticorps détectés demandent une interprétation spécialisée. Une présentation séronégative n’autorise ni à affirmer automatiquement la maladie ni à l’exclure.'),(13,21))
l.add('Le {diagnostic associe clinique et preuves complémentaires}. Il n’exige pas que tous les tests soient positifs. Les imitateurs doivent être recherchés si les résultats restent discordants.',paras('La fatigabilité et la fluctuation évocatrices sont rapprochées des anticorps, de l’électrophysiologie et, dans des situations sélectionnées, d’un test pharmacologique surveillé. Une réponse subjective à un médicament ne suffit pas seule.', 'Les anticorps dirigés contre le récepteur de l’acétylcholine sont moins souvent détectés dans la forme oculaire que dans la forme généralisée selon le CEN. Une sérologie négative peut conduire à des tests complémentaires, à une répétition ou à une révision du diagnostic selon le contexte.', 'Une myopathie oculaire chronique, une orbitopathie restrictive, une paralysie de nerf crânien ou une décompensation strabique figurent parmi les diagnostics différentiels. Les signes sensitifs ou centraux demandent une autre localisation.'),(5,11,13,21))
l.add('Les {examens documentent la transmission et recherchent un thymome}. L’électrophysiologie doit être adaptée à la présentation. Le bilan s’interprète avec la clinique.',paras('9.a. Il n’existe pas de test unique suffisamment sensible pour toutes les formes oculaires. La confirmation spécialisée combine plusieurs arguments.', '9.b. Rechercher les anticorps anti-récepteurs de l’acétylcholine, puis les autres anticorps selon le contexte. La stimulation répétitive peut montrer un décrément ; l’examen de fibre unique peut aider si les premiers résultats sont négatifs.', '9.c. Une stimulation périphérique normale n’exclut pas une atteinte oculaire. Si la suspicion persiste, orienter vers un centre neuromusculaire expérimenté. Les tests pharmacologiques comportent des risques et ne se pratiquent pas comme une épreuve à domicile.', '9.d. Une imagerie thoracique par scanner ou IRM recherche un thymome selon la recommandation allemande. Le protocole est choisi avec l’équipe, particulièrement dans une maladie instable. Rechercher les maladies auto-immunes associées selon les signes.')+table(['Résultat','Décision'],[['La sérologie est positive et la clinique compatible.','Confirmer le sous-groupe et établir le bilan de sévérité.'],['La sérologie et les premiers tests sont négatifs, mais la clinique évocatrice.','Compléter ou répéter les examens spécialisés et rechercher les imitateurs.'],['Une anomalie thymique est trouvée.','Discussion neurologique, radiologique et chirurgicale spécialisée.'],['Une faiblesse respiratoire ou bulbaire apparaît.','Priorité à l’évaluation urgente, sans attendre la fin du bilan étiologique.']]),(13,21))
l.add('L’{algorithme commence par la respiration et la déglutition}. Confirmer ensuite le mécanisme et évaluer le handicap. Ajuster le suivi à la réponse et au risque de généralisation.',steps('Écarter détresse respiratoire, fausses routes importantes et aggravation rapide.', 'Décrire ptosis, diplopie fluctuante et fatigabilité avec examen neurologique.', 'Obtenir sérologie, électrophysiologie adaptée et exploration thymique.', 'Choisir traitement symptomatique puis traitement immunologique si indiqué.', 'Réévaluer vision, tolérance, signes extraoculaires et besoins de soutien.'),(13,14,21))
m=mestinon(l)
l.add('Le {traitement associe contrôle des symptômes et de la maladie}. La pyridostigmine peut améliorer la gêne sans suffire à contrôler la diplopie. Un traitement immunologique relève du neurologue.',paras('11.A. Définir les objectifs fonctionnels avec le patient et vérifier que la présentation reste limitée aux yeux. Une occlusion temporaire ou un prisme sélectionné peut aider, mais la variabilité réduit parfois leur utilité.', '11.B. La dose, la forme et la sécurité suisses de la pyridostigmine sont détaillées dans la fenêtre suivante. '+m, '11.B. La recommandation allemande indique que les anticholinestérasiques seuls sont souvent insuffisants dans les formes oculaires gênantes. Une corticothérapie puis, selon la réponse, une stratégie d’épargne immunosuppressive peuvent être discutées ; l’introduction des corticoïdes peut aggraver transitoirement la myasthénie et doit être encadrée.', '11.B. La thymectomie dépend notamment d’un thymome et du phénotype. Elle n’est pas un traitement automatique de toute diplopie myasthénique isolée. La chirurgie de strabisme n’est envisagée qu’après contrôle et stabilité, dans des cas sélectionnés.', '11.C. Une crise nécessite une surveillance hospitalière spécialisée, un soutien respiratoire si nécessaire et une immunothérapie rapide telle que les échanges plasmatiques ou les immunoglobulines selon le contexte. Le présent cours ne fournit pas un protocole de réanimation individualisé.', '11.D. Organiser le suivi neurologique et ophtalmologique, la conciliation médicamenteuse et les adaptations scolaires ou professionnelles. Fournir les signes d’alarme au patient et à l’entourage, avec une conduite claire en cas d’infection, de nouvelle prescription ou de grossesse.'),(3,13,14,21))
l.add('La {prévention vise les facteurs d’aggravation et les complications}. Éviter l’automodification des doses et vérifier les nouvelles prescriptions. Maintenir le suivi même après amélioration oculaire.',paras('La prévention primaire ne permet pas actuellement d’éviter toutes les myasthénies auto-immunes. La prévention secondaire identifie rapidement les signes bulbaires ou respiratoires et les effets médicamenteux.', 'La prévention tertiaire associe traitement adapté, suivi des effets indésirables, adaptation des activités et information des soignants avant anesthésie. Les mesures vaccinales et la prévention infectieuse sont individualisées avec les immunothérapies prescrites.'),(13,14,21))
l.add('Les {points clés sont fluctuation, tests parfois négatifs et sécurité respiratoire}. Le ptosis n’est pas toujours constant. Une faiblesse nouvelle peut venir de la maladie ou du traitement.',paras('La sérologie négative ne clôt pas un bilan évocateur. Une mydriase impose une autre explication. La pyridostigmine ne traite pas l’auto-immunité et sa dose ne s’augmente pas seul. Fausses routes, toux inefficace et dyspnée imposent une évaluation urgente.'),(13,14,21))
l.quiz([('Quel mécanisme explique la fatigabilité ?','Un défaut de transmission à la jonction neuromusculaire.'),('Le repos peut-il améliorer le ptosis ?','Oui.'),('Une pupille nouvellement dilatée est-elle typique ?','Non ; rechercher une autre cause.'),('Une présentation oculaire peut-elle se généraliser ?','Oui.'),('Faut-il attendre deux ans pour traiter une présentation oculaire ?','Non.'),('Une sérologie négative exclut-elle la maladie ?','Non.'),('Un examen électrophysiologique périphérique normal suffit-il à exclure la forme oculaire ?','Non.'),('Le test au glaçon est-il une preuve isolée définitive ?','Non.'),('Faut-il rechercher un thymome ?','Oui, dans le bilan spécialisé.'),('La pyridostigmine supprime-t-elle l’auto-immunité ?','Non.'),('La dragée de 60 mg est-elle identique au comprimé retard de 180 mg ?','Non.'),('Une atteinte rénale peut-elle modifier la dose ?','Oui ; adaptation individuelle selon la réponse et la tolérance.'),('Une faiblesse avec hypersécrétions autorise-t-elle une augmentation spontanée ?','Non ; une crise cholinergique est possible.'),('Que faire devant toux inefficace et dyspnée ?','Obtenir une prise en charge urgente.')],(13,14,21))
l.write()
